    static final Map<String, String[]> MAP = new HashMap<>();
    static int idx = 0;

    static void build() {
        if (!MAP.isEmpty()) return;
        for (String r : ROWS) {
            String[] f = r.split("\t", -1);
            if (f.length >= 11) MAP.put(f[0], f);
        }
    }

    public static void init(Context c) {
        build();
        SharedPreferences p = c.getSharedPreferences("mac", 0);
        String code = p.getString("lang", "en");
        idx = 0;
        for (int i = 0; i < CODES.length; i++) if (CODES[i].equals(code)) idx = i;
    }

    public static void set(Context c, int i) {
        c.getSharedPreferences("mac", 0).edit().putString("lang", CODES[i]).apply();
        idx = i;
    }

    public static int index() { return idx; }
    public static boolean rtl() { return idx == 3; }

    public static Locale locale() {
        switch (idx) {
            case 1: return new Locale("ko");
            case 2: return new Locale("in", "ID");
            case 3: return Locale.forLanguageTag("ar-u-nu-latn");
            case 4: return new Locale("ru");
            case 5: return new Locale("ms", "MY");
            case 6: return new Locale("pt", "BR");
            case 7: return Locale.FRENCH;
            case 8: return new Locale("es");
            case 9: return new Locale("vi");
            case 10: return Locale.forLanguageTag("hi-u-nu-latn");
            default: return Locale.US;
        }
    }

    /** Translate an English UI string. Unknown strings pass through unchanged. */
    public static String t(String s) {
        if (idx == 0 || s == null || s.isEmpty()) return s;
        build();
        String[] f = MAP.get(s);
        if (f != null) return f[idx];
        // "Name…" / trailing ellipsis variants and "Hide Finder"-style prefixes
        String[] pre = {"Hide ", "Quit ", "About ", "New "};
        for (String p : pre) {
            if (s.startsWith(p) && s.length() > p.length()) {
                String[] g = MAP.get(p.trim());
                String[] n = MAP.get(s.substring(p.length()));
                if (g != null && n != null && !p.equals("About ") && !p.equals("New ")) return g[idx] + " " + n[idx];
            }
        }
        return s;
    }
